local Players = game:GetService(\"Players\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal player = Players.LocalPlayer\n\n-- ============================================================================\n-- UTILITIES MODULE (Embedded)\n-- ============================================================================\nlocal Utilities = {}\n\nfunction Utilities.getPlayer()\n    return game.Players.LocalPlayer\nend\n\nfunction Utilities.getCharacter(player)\n    if not player then\n        player = Utilities.getPlayer()\n    end\n\n    if player and player.Character then\n        return player.Character\n    end\n\n    return nil\nend\n\nfunction Utilities.getHumanoid(player)\n    local character = Utilities.getCharacter(player)\n    if not character then\n        return nil\n    end\n\n    return character:FindFirstChildOfClass(\"Humanoid\")\nend\n\nfunction Utilities.getRootPart(player)\n    local character = Utilities.getCharacter(player)\n    if not character then\n        return nil\n    end\n\n    return character:FindFirstChild(\"HumanoidRootPart\")\nend\n\nfunction Utilities.waitForCharacter(player)\n    if not player then\n        player = Utilities.getPlayer()\n    end\n\n    if player.Character then\n        return player.Character\n    end\n\n    return player.CharacterAdded:Wait()\nend\n\nfunction Utilities.makeDraggable(frame, dragZone)\n    local dragging = false\n    local dragStartPosition = nil\n    local originalPosition = nil\n\n    local zone = dragZone or frame\n\n    zone.InputBegan:Connect(function(input)\n        if input.UserInputType ~= Enum.UserInputType.Touch then\n            return\n        end\n\n        dragging = true\n        dragStartPosition = input.Position\n        originalPosition = frame.Position\n    end)\n\n    zone.InputEnded:Connect(function(input)\n        if input.UserInputType ~= Enum.UserInputType.Touch then\n            return\n        end\n\n        dragging = false\n    end)\n\n    UserInputService.InputChanged:Connect(function(input)\n        if input.UserInputType ~= Enum.UserInputType.Touch then\n            return\n        end\n\n        if dragging and dragStartPosition and originalPosition then\n            local delta = input.Position - dragStartPosition\n            frame.Position = UDim2.new(\n                originalPosition.X.Scale,\n                originalPosition.X.Offset + delta.X,\n                originalPosition.Y.Scale,\n                originalPosition.Y.Offset + delta.Y\n            )\n        end\n    end)\n\n    return {\n        start = function()\n            dragging = true\n        end,\n\n        stop = function()\n            dragging = false\n        end,\n    }\nend\n\n-- ============================================================================\n-- MOVEMENT MODULE (Embedded)\n-- ============================================================================\nlocal Movement = {}\n\nfunction Movement.getPlayer()\n    return Utilities.getPlayer()\nend\n\nfunction Movement.getCharacter(player)\n    return Utilities.getCharacter(player)\nend\n\nfunction Movement.getHumanoid(player)\n    return Utilities.getHumanoid(player)\nend\n\nfunction Movement.getRootPart(player)\n    return Utilities.getRootPart(player)\nend\n\nfunction Movement.waitForCharacter(player)\n    return Utilities.waitForCharacter(player)\nend\n\nfunction Movement.resetCharacterState(player)\n    local character = Utilities.getCharacter(player)\n    if not character then\n        return\n    end\n\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    if humanoid then\n        humanoid.WalkSpeed = 16\n        humanoid.JumpPower = 50\n    end\nend\n\n-- ============================================================================\n-- SPEED MODULE (Embedded)\n-- ============================================================================\nlocal Speed = {\n    defaultSpeed = 16,\n    boostedSpeed = 60,\n}\n\nfunction Speed.setEnabled(player, enabled)\n    local character = Movement.getCharacter(player)\n    if not character then\n        return\n    end\n\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    if not humanoid then\n        return\n    end\n\n    if enabled then\n        humanoid.WalkSpeed = Speed.boostedSpeed\n    else\n        humanoid.WalkSpeed = Speed.defaultSpeed\n    end\nend\n\nfunction Speed.setSpeed(player, value)\n    local character = Movement.getCharacter(player)\n    if not character then\n        return\n    end\n\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    if not humanoid then\n        return\n    end\n\n    humanoid.WalkSpeed = value\nend\n\n-- ============================================================================\n-- FLIGHT MODULE (Embedded)\n-- ============================================================================\nlocal Flight = {\n    enabled = false,\n    renderConnection = nil,\n    inputConnection = nil,\n}\n\nfunction Flight.start(player)\n    if not player then\n        return\n    end\n\n    local character = player.Character\n    if not character then\n        return\n    end\n\n    local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    if not rootPart or not humanoid then\n        return\n    end\n\n    if Flight.renderConnection then\n        Flight.renderConnection:Disconnect()\n        Flight.renderConnection = nil\n    end\n\n    if Flight.inputConnection then\n        Flight.inputConnection:Disconnect()\n        Flight.inputConnection = nil\n    end\n\n    Flight.enabled = true\n\n    Flight.renderConnection = RunService.RenderStepped:Connect(function()\n        if not player.Character then\n            Flight.stop(player)\n            return\n        end\n\n        local currentCharacter = player.Character\n        local currentRoot = currentCharacter:FindFirstChild(\"HumanoidRootPart\")\n        local currentHumanoid = currentCharacter:FindFirstChildOfClass(\"Humanoid\")\n\n        if not currentRoot or not currentHumanoid then\n            return\n        end\n\n        if not Flight.enabled then\n            return\n        end\n\n        local currentVelocity = currentRoot.AssemblyLinearVelocity\n        currentRoot.AssemblyLinearVelocity = Vector3.new(currentVelocity.X, 18, currentVelocity.Z)\n        currentHumanoid:ChangeState(Enum.HumanoidStateType.Freefall)\n    end)\n\n    Flight.inputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n        if gameProcessed then\n            return\n        end\n\n        if input.KeyCode == Enum.KeyCode.Space and Flight.enabled then\n            local currentCharacter = player.Character\n            if not currentCharacter then\n                return\n            end\n\n            local currentRoot = currentCharacter:FindFirstChild(\"HumanoidRootPart\")\n            if currentRoot then\n                local velocity = currentRoot.AssemblyLinearVelocity\n                currentRoot.AssemblyLinearVelocity = Vector3.new(velocity.X, velocity.Y + 20, velocity.Z)\n            end\n        end\n    end)\nend\n\nfunction Flight.stop(player)\n    if Flight.renderConnection then\n        Flight.renderConnection:Disconnect()\n        Flight.renderConnection = nil\n    end\n\n    if Flight.inputConnection then\n        Flight.inputConnection:Disconnect()\n        Flight.inputConnection = nil\n    end\n\n    Flight.enabled = false\n\n    if player and player.Character then\n        local currentRoot = player.Character:FindFirstChild(\"HumanoidRootPart\")\n        if currentRoot then\n            local velocity = currentRoot.AssemblyLinearVelocity\n            currentRoot.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)\n        end\n    end\nend\n\nfunction Flight.setEnabled(player, enabled)\n    if enabled then\n        Flight.start(player)\n    else\n        Flight.stop(player)\n    end\nend\n\n-- ============================================================================\n-- INFINITE JUMP MODULE (Embedded)\n-- ============================================================================\nlocal InfiniteJump = {\n    enabled = false,\n    connection = nil,\n}\n\nfunction InfiniteJump.setEnabled(player, enabled)\n    if not player then\n        return\n    end\n\n    if enabled then\n        if InfiniteJump.connection then\n            return\n        end\n\n        InfiniteJump.enabled = true\n\n        InfiniteJump.connection = UserInputService.JumpRequest:Connect(function()\n            local character = player.Character\n            if not character then\n                return\n            end\n\n            local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n            if not humanoid then\n                return\n            end\n\n            if humanoid:GetState() ~= Enum.HumanoidStateType.Landed then\n                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)\n            end\n        end)\n    else\n        InfiniteJump.enabled = false\n\n        if InfiniteJump.connection then\n            InfiniteJump.connection:Disconnect()\n            InfiniteJump.connection = nil\n        end\n    end\nend\n\n-- ============================================================================\n-- NOCLIP MODULE (Embedded)\n-- ============================================================================\nlocal NoClip = {\n    enabled = false,\n    characterConnection = nil,\n}\n\nlocal function setCharacterCollision(character, canCollide)\n    if not character then\n        return\n    end\n\n    for _, descendant in ipairs(character:GetDescendants()) do\n        if descendant:IsA(\"BasePart\") then\n            descendant.CanCollide = canCollide\n        end\n    end\nend\n\nfunction NoClip.setEnabled(player, enabled)\n    if not player then\n        return\n    end\n\n    local character = Movement.getCharacter(player)\n    if character then\n        setCharacterCollision(character, not enabled)\n    end\n\n    if enabled then\n        NoClip.enabled = true\n\n        if NoClip.characterConnection then\n            NoClip.characterConnection:Disconnect()\n        end\n\n        NoClip.characterConnection = player.CharacterAdded:Connect(function(newCharacter)\n            task.wait(0.1)\n            setCharacterCollision(newCharacter, false)\n        end)\n    else\n        NoClip.enabled = false\n\n        if NoClip.characterConnection then\n            NoClip.characterConnection:Disconnect()\n            NoClip.characterConnection = nil\n        end\n\n        if player.Character then\n            setCharacterCollision(player.Character, true)\n        end\n    end\nend\n\n-- ============================================================================\n-- GUI MODULE (Embedded)\n-- ============================================================================\nlocal GUI = {}\n\nlocal function createRoundedFrame(parent, name, size, position, color)\n    local frame = Instance.new(\"Frame\")\n    frame.Name = name\n    frame.Size = size\n    frame.Position = position\n    frame.BackgroundColor3 = color\n    frame.BorderSizePixel = 0\n    frame.Parent = parent\n\n    local corner = Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, 16)\n    corner.Parent = frame\n\n    return frame\nend\n\nlocal function createTextLabel(parent, name, text, size, position, fontSize, textColor, alignment)\n    local label = Instance.new(\"TextLabel\")\n    label.Name = name\n    label.Size = size\n    label.Position = position\n    label.Text = text\n    label.BackgroundTransparency = 1\n    label.Font = Enum.Font.GothamBold\n    label.TextSize = fontSize\n    label.TextColor3 = textColor\n    label.TextXAlignment = alignment or Enum.TextXAlignment.Left\n    label.Parent = parent\n    return label\nend\n\nlocal function createTextButton(parent, name, text, size, position, color, textColor)\n    local button = Instance.new(\"TextButton\")\n    button.Name = name\n    button.Size = size\n    button.Position = position\n    button.BackgroundColor3 = color\n    button.BorderSizePixel = 0\n    button.Text = text\n    button.TextColor3 = textColor\n    button.Font = Enum.Font.GothamBold\n    button.TextSize = 15\n    button.AutoButtonColor = false\n    button.Parent = parent\n\n    local corner = Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, 12)\n    corner.Parent = button\n\n    return button\nend\n\nfunction GUI.create(player)\n    local playerGui = player:WaitForChild(\"PlayerGui\")\n\n    local screenGui = Instance.new(\"ScreenGui\")\n    screenGui.Name = \"FeatureManagerGui\"\n    screenGui.ResetOnSpawn = false\n    screenGui.IgnoreGuiInset = true\n    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n    screenGui.Parent = playerGui\n\n    local panel = createRoundedFrame(screenGui, \"Panel\", UDim2.new(0, 260, 0, 250), UDim2.new(0, 18, 0, 120), Color3.fromRGB(20, 20, 25))\n\n    local header = createRoundedFrame(panel, \"Header\", UDim2.new(1, 0, 0, 42), UDim2.new(0, 0, 0, 0), Color3.fromRGB(35, 35, 40))\n    local headerTitle = createTextLabel(header, \"Title\", \"Player Tools\", UDim2.new(1, -20, 1, 0), UDim2.new(0, 10, 0, 0), 18, Color3.fromRGB(255, 255, 255), Enum.TextXAlignment.Left)\n\n    local featureContainer = Instance.new(\"Frame\")\n    featureContainer.Name = \"FeatureContainer\"\n    featureContainer.Size = UDim2.new(1, -14, 1, -68)\n    featureContainer.Position = UDim2.new(0, 7, 0, 52)\n    featureContainer.BackgroundTransparency = 1\n    featureContainer.Parent = panel\n\n    local layout = Instance.new(\"UIListLayout\")\n    layout.Padding = UDim.new(0, 8)\n    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n    layout.Parent = featureContainer\n\n    local featureButtons = {}\n    local toggleStates = {}\n    local toggleCallbacks = {}\n\n    local function setFeatureState(name, enabled)\n        toggleStates[name] = enabled\n        local button = featureButtons[name]\n        if button then\n            button.Text = name .. \": \" .. (enabled and \"ON\" or \"OFF\")\n            button.BackgroundColor3 = enabled and Color3.fromRGB(54, 174, 90) or Color3.fromRGB(93, 96, 108)\n        end\n    end\n\n    local featureOrder = {\n        \"Speed\",\n        \"Flight\",\n        \"Infinite Jump\",\n        \"No Clip\",\n    }\n\n    for _, featureName in ipairs(featureOrder) do\n        local button = createTextButton(featureContainer, featureName .. \"Button\", featureName .. \": OFF\", UDim2.new(1, -6, 0, 34), UDim2.new(0, 0, 0, 0), Color3.fromRGB(93, 96, 108), Color3.fromRGB(255, 255, 255))\n        featureButtons[featureName] = button\n        toggleStates[featureName] = false\n\n        button.MouseButton1Click:Connect(function()\n            toggleStates[featureName] = not toggleStates[featureName]\n            setFeatureState(featureName, toggleStates[featureName])\n\n            if toggleCallbacks[featureName] then\n                toggleCallbacks[featureName](toggleStates[featureName])\n            end\n        end)\n    end\n\n    local resetButton = createTextButton(panel, \"ResetButton\", \"Reset / Disable All\", UDim2.new(1, -14, 0, 38), UDim2.new(0, 7, 0, 198), Color3.fromRGB(176, 58, 58), Color3.fromRGB(255, 255, 255))\n    local resetCallback = nil\n\n    resetButton.MouseButton1Click:Connect(function()\n        if resetCallback then\n            resetCallback()\n        end\n    end)\n\n    Utilities.makeDraggable(panel, header)\n\n    local guiApi = {}\n\n    function guiApi.bindToggle(featureName, callback)\n        toggleCallbacks[featureName] = callback\n        if callback then\n            if toggleStates[featureName] == nil then\n                toggleStates[featureName] = false\n            end\n            setFeatureState(featureName, toggleStates[featureName])\n        end\n    end\n\n    function guiApi.bindReset(callback)\n        resetCallback = callback\n    end\n\n    function guiApi.setToggle(featureName, enabled)\n        setFeatureState(featureName, enabled)\n        toggleStates[featureName] = enabled\n    end\n\n    function guiApi.destroy()\n        screenGui:Destroy()\n    end\n\n    return guiApi\nend\n\n-- ============================================================================\n-- MAIN INITIALIZATION\n-- ============================================================================\nlocal state = {\n    speed = false,\n    flight = false,\n    infiniteJump = false,\n    noclip = false,\n}\n\nlocal featureGui = nil\n\nlocal function refreshGui()\n    if not featureGui then\n        return\n    end\n\n    featureGui.setToggle(\"Speed\", state.speed)\n    featureGui.setToggle(\"Flight\", state.flight)\n    featureGui.setToggle(\"Infinite Jump\", state.infiniteJump)\n    featureGui.setToggle(\"No Clip\", state.noclip)\nend\n\nlocal function resetAllFeatures()\n    state.speed = false\n    state.flight = false\n    state.infiniteJump = false\n    state.noclip = false\n\n    Speed.setEnabled(player, false)\n    Flight.setEnabled(player, false)\n    InfiniteJump.setEnabled(player, false)\n    NoClip.setEnabled(player, false)\n\n    refreshGui()\nend\n\nlocal function setupCharacterSync()\n    local function syncCurrentCharacter()\n        if state.speed then\n            Speed.setEnabled(player, true)\n        end\n\n        if state.flight then\n            Flight.setEnabled(player, true)\n        end\n\n        if state.infiniteJump then\n            InfiniteJump.setEnabled(player, true)\n        end\n\n        if state.noclip then\n            NoClip.setEnabled(player, true)\n        end\n    end\n\n    syncCurrentCharacter()\n\n    player.CharacterAdded:Connect(function()\n        task.wait(0.2)\n        syncCurrentCharacter()\n    end)\nend\n\nlocal function initialize()\n    Movement.resetCharacterState(player)\n\n    featureGui = GUI.create(player)\n\n    featureGui.bindToggle(\"Speed\", function(enabled)\n        state.speed = enabled\n        Speed.setEnabled(player, enabled)\n    end)\n\n    featureGui.bindToggle(\"Flight\", function(enabled)\n        state.flight = enabled\n        Flight.setEnabled(player, enabled)\n    end)\n\n    featureGui.bindToggle(\"Infinite Jump\", function(enabled)\n        state.infiniteJump = enabled\n        InfiniteJump.setEnabled(player, enabled)\n    end)\n\n    featureGui.bindToggle(\"No Clip\", function(enabled)\n        state.noclip = enabled\n        NoClip.setEnabled(player, enabled)\n    end)\n\n    featureGui.bindReset(function()\n        resetAllFeatures()\n    end)\n\n    refreshGui()\n    setupCharacterSync()\nend\n\ninitialize()\n"